import { sql } from 'drizzle-orm'
import { customType, timestamp, uuid } from 'drizzle-orm/pg-core'

/**
 * Primary key as UUID v7, generated by Postgres 18: unique like v4, but time-ordered,
 * so new rows go to the end of the index instead of random pages.
 */
export const id = () =>
  uuid()
    .primaryKey()
    .default(sql`uuidv7()`)

export const timestamps = {
  createdAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp({ withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
}

/** A GPS position in WGS 84 degrees, in the same order map libraries use: longitude first. */
export type GeoPoint = { lng: number; lat: number }

/** Reads the hex EWKB Postgres returns for a geometry: a byte-order flag, the type, then x and y. */
export function parseEwkbPoint(hex: string): GeoPoint {
  const bytes = Buffer.from(hex, 'hex')
  const littleEndian = bytes.readUInt8(0) === 1
  const type = littleEndian ? bytes.readUInt32LE(1) : bytes.readUInt32BE(1)
  if ((type & 0xffff) !== 1) throw new Error('Expected a POINT geometry')

  const hasSrid = (type & 0x20000000) !== 0
  const offset = hasSrid ? 9 : 5
  const read = (at: number) => (littleEndian ? bytes.readDoubleLE(at) : bytes.readDoubleBE(at))
  return { lng: read(offset), lat: read(offset + 8) }
}

/**
 * A point column with SRID 4326 (GPS coordinates). Drizzle's built-in geometry() drops the SRID,
 * which would store points with SRID 0 and break distance calculations in metres.
 */
export const geoPoint = customType<{ data: GeoPoint; driverData: string }>({
  dataType: () => 'geometry(Point, 4326)',
  toDriver: ({ lng, lat }) => `SRID=4326;POINT(${lng} ${lat})`,
  fromDriver: parseEwkbPoint,
})
